mapper.select:
SELECT A.INT_RATE_ID AS intRateId, /**利率代码**/ '' as rateName, A.RELAESE_DATE AS relaeseDate, /**发布日**/ A.EFF_DATE AS effDate, /**生效日**/ A.INT_RATE*100 AS intRate, /**利率值(%)**/ '' AS quoCcy FROM MST_INT_RATE_INFO A WHERE 1=1
AND A.INT_RATE_ID LIKE concat_ws('','%',#{params.intRateId},'%')
AND A.RELAESE_DATE >= #{params.relaeseStartDate}
AND A.RELAESE_DATE <=#{params.relaeseEndDate}
AND A.EFF_DATE >= #{params.effStartDate}
AND A.EFF_DATE <= #{params.effEndDate}
